// Domain 3 — ICMP, UDP and TCP. Original flashcards.
let n = 0;
const c = (topic, front, back) => ({ id: `d3-f${String(++n).padStart(3, '0')}`, topic, front, back });

export default [
  c('3.1', 'ICMP IP protocol number and header start?', 'Protocol 1. Type (1 byte), code (1), checksum (2), then 4 type-specific bytes. No ports.'),
  c('3.1', 'ICMP types 0, 8, 3, 5, 11, 12?', '0 echo reply, 8 echo request, 3 destination unreachable, 5 redirect, 11 time exceeded, 12 parameter problem.'),
  c('3.1', 'Key type 3 codes?', '0 net, 1 host, 2 protocol, 3 port, 4 fragmentation needed and DF set, 9/10 net/host administratively prohibited, 13 communication administratively prohibited.'),
  c('3.1', 'What does an ICMP error quote?', 'The original IP header plus at least the first 8 bytes of its payload, so the sender can match the socket.'),
  c('3.1', 'Why is TTL in a ping reply not the sent TTL?', 'It is the TTL on arrival. Initial values: Linux 64, Windows 128, Cisco IOS 255. Subtract the reply to estimate hops, as an inference only.'),
  c('3.1', 'How does traceroute find each hop?', 'Probes with TTL 1, 2, 3...; each router that drops TTL 0 returns ICMP type 11 code 0 from one of its addresses.'),
  c('3.1', 'Unix traceroute versus Windows tracert probes?', 'Unix and IOS: UDP to ports from 33434, ends on type 3 code 3. Windows tracert: ICMP echo, ends on echo reply.'),
  c('3.1', 'IOS ping characters ! . U M Q?', '! reply, . timeout, U unreachable, M could not fragment (type 3 code 4), Q source quench (legacy).'),
  c('3.1', 'When does a router send an ICMP redirect?', 'Packet leaves the interface it arrived on and the sender is on the same subnet as the better next hop. Type 5; code 0 network, 1 host.'),
  c('3.1', 'Is ICMP Source Quench still used?', 'No. Deprecated by RFC 6633: routers must not send it, hosts must not act on it.'),
  c('3.1', 'Which ICMP must never be blanket-blocked?', 'Type 3 code 4 (PMTUD) and type 11 (traceroute, reassembly timeout); rate-limit ICMP instead of dropping it.'),
  c('3.2', 'MTU versus MSS?', 'MTU: largest IP packet per link (1500). MSS: largest TCP payload (1460), announced in the SYN MSS option.'),
  c('3.2', 'What happens to a packet larger than the egress MTU?', 'DF clear: the router fragments it. DF set: dropped with ICMP type 3 code 4 carrying the Next-Hop MTU.'),
  c('3.2', 'Who reassembles fragments?', 'Only the destination host, matching source, destination, protocol and Identification. Losing one fragment loses the datagram.'),
  c('3.2', 'How does classic PMTUD (RFC 1191) work?', 'Send with DF set; a router that cannot forward returns type 3 code 4 with Next-Hop MTU; the sender caches the lower PMTU (Linux about 10 minutes) and shrinks segments.'),
  c('3.2', 'Symptom of a PMTUD black hole?', 'Handshake and small requests work; large transfers stall with repeated retransmissions of full-size segments, because the type 3 code 4 is blocked.'),
  c('3.2', 'PLPMTUD (RFC 4821) in one line?', 'Probes with larger segments and infers the path MTU from acknowledgments, not ICMP. Linux: net.ipv4.tcp_mtu_probing (default 0).'),
  c('3.2', 'Overhead: PPPoE, IP-in-IP, GRE, VXLAN?', '8, 20, 24 (20 IP + 4 GRE) and 50 bytes. Tunnel MTUs on 1500: 1492, 1480, 1476.'),
  c('3.2', 'How do you clamp the MSS?', 'IOS: ip tcp adjust-mss N on the interface. Linux: iptables -t mangle ... -j TCPMSS --clamp-mss-to-pmtu. Set N = MTU - 40.'),
  c('3.2', 'Test the path MTU from a host?', 'Linux: ping -M do -s 1472 host. Windows: ping -f -l 1472 host. IOS: ping x size 1500 df-bit. 1472 + 28 = 1500.'),
  c('3.3', 'UDP header fields?', '8 bytes: source port, destination port, length (header + data), checksum. IP protocol 17.'),
  c('3.3', 'What does UDP not provide?', 'No handshake, ordering, retransmission, flow or congestion control. Message boundaries are preserved.'),
  c('3.3', 'IPv4 UDP checksum zero?', 'Means the sender did not compute it; optional on IPv4, mandatory on IPv6. Maximum IPv4 payload is 65507 bytes.'),
  c('3.3', 'RFC 6335 port ranges?', 'System 0-1023, User 1024-49151, Dynamic or private 49152-65535.'),
  c('3.3', 'Default ephemeral ports: Linux versus Windows?', 'Linux 32768-60999 (net.ipv4.ip_local_port_range). Windows Vista and later: 49152-65535.'),
  c('3.3', 'What is the 5-tuple?', 'Protocol, source IP, source port, destination IP, destination port. It identifies a flow and is the key in firewall and NAT tables.'),
  c('3.3', 'Closed UDP port response?', 'ICMP type 3 code 3. A closed TCP port answers with RST.'),
  c('3.3', 'DNS, DHCP, NTP, SNMP, syslog, TFTP ports?', 'DNS 53 UDP/TCP; DHCP 67 server and 68 client; NTP 123; SNMP 161 (traps 162); syslog 514; TFTP 69 (all UDP).'),
  c('3.3', 'HTTP, HTTPS, SSH, BGP ports?', 'TCP 80, 443, 22 and 179. QUIC (HTTP/3) uses UDP 443.'),
  c('3.4', 'TCP header size and flags?', '20 bytes minimum, 60 maximum (Data Offset 4 bits, in words). Flags: CWR ECE URG ACK PSH RST SYN FIN.'),
  c('3.4', 'Flag byte values?', 'FIN 0x01, SYN 0x02, RST 0x04, PSH 0x08, ACK 0x10, URG 0x20, ECE 0x40, CWR 0x80. SYN-ACK is 0x12.'),
  c('3.4', 'Which options exist only in SYNs?', 'MSS (kind 2), window scale (kind 3, shift 0-14) and SACK permitted (kind 4). Timestamps (kind 8) and SACK blocks (kind 5) appear later.'),
  c('3.4', 'Sequence and acknowledgment arithmetic?', 'ACK is the next byte expected. SYN and FIN each consume one sequence number; a pure ACK consumes none.'),
  c('3.4', 'Three-way handshake?', 'SYN (seq x), SYN-ACK (seq y, ack x+1), ACK (ack y+1). A closed port answers RST-ACK.'),
  c('3.4', 'TCP teardown?', 'FIN/ACK in each direction: four segments, or three if merged. Half-close is legal. RST aborts immediately.'),
  c('3.4', 'TIME-WAIT: who, why and how long?', 'The active closer. To re-ACK a retransmitted FIN and let old duplicates expire. 2 x MSL; Linux fixed 60 s, Windows tunable.'),
  c('3.4', 'Many CLOSE-WAIT sockets?', 'The peer closed but the local application never closed its socket: an application bug, and they do not time out.'),
  c('3.4', 'Window scale limits?', 'Shift 0-14 negotiated in both SYNs (both must send it); maximum window 65,535 x 2^14 = 1,073,725,440 bytes.'),
  c('3.4', 'Throughput limit from the window?', 'Throughput <= window / RTT. A 64 KB window at 80 ms RTT is about 6.5 Mbit/s whatever the link speed.'),
  c('3.4', 'Fast retransmit and SACK?', 'Three duplicate ACKs trigger an immediate retransmission. SACK (SYN option 4, blocks option 5) lists out-of-order ranges, up to 4 blocks (3 with timestamps).'),
  c('3.4', 'RTO basics?', 'Initial 1 s, RTO = SRTT + 4 x RTTVAR, doubles per timeout, no RTT samples from retransmissions (Karn). Linux minimum is 200 ms.'),
  c('3.4', 'Slow start versus congestion avoidance?', 'cwnd < ssthresh: +1 SMSS per ACK (doubles per RTT). Above: about +1 SMSS per RTT. Initial window is typically 10 segments (RFC 6928).'),
  c('3.4', 'Reaction to loss?', 'Timeout: cwnd = 1 SMSS, slow start. Three dup ACKs: ssthresh = max(flight/2, 2 SMSS), fast recovery.'),
  c('3.4', 'How does ECN work?', 'Router sets CE (IP ECN bits 11) instead of dropping; receiver echoes with ECE; sender halves cwnd and sets CWR. SYN carries ECE+CWR, SYN-ACK only ECE.'),
];
